$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot '..\meeting_pack.ps1');$root=Join-Path $env:TEMP ('sami-mp-test-'+[guid]::NewGuid().ToString('n'));$data=Join-Path $root 'data';New-Item -ItemType Directory -Path $data -Force|Out-Null
try{$source=Join-Path $data 'projects.json';Copy-Item -LiteralPath (Join-Path $PSScriptRoot '..\data\projects.example.json') -Destination $source;$revision=Get-MeetingPackRevision $source;$body=@{format='md';mode='authorised';scope='Entire portfolio';projectIds=@();revision=$revision}|ConvertTo-Json;$result=Invoke-MeetingPackExport $body $source $source $root $true;if($result.Bytes.Length-lt100){throw'Authorised export was empty.'};$audit=Join-Path $data 'meeting_pack_exports.jsonl';if(-not(Test-Path -LiteralPath $audit)){throw'Authorised export audit missing.'};'MEETING_PACK_NO_PIN_OK'}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}
